<style scoped>
.fp-logo {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.fp-logo__plate {
  opacity: 0;
  filter: blur(24px);
  animation: fp-plate-focus-in 820ms cubic-bezier(0.16, 1, 0.3, 1) 180ms both;
}

.fp-logo__monogram-trace {
  opacity: 0;
  stroke-dasharray: 1 1;
  stroke-dashoffset: -1;
  animation: fp-monogram-trace 1.65s cubic-bezier(0.45, 0, 0.2, 1) 1.05s both;
}

.fp-logo__monogram-fill {
  opacity: 0;
  animation: fp-monogram-fill 140ms ease-out 2.62s both;
}

@keyframes fp-plate-focus-in {
  from {
    opacity: 0;
    filter: blur(24px);
  }
  to {
    opacity: 1;
    filter: blur(1px);
  }
}

@keyframes fp-monogram-trace {
  0% {
    opacity: 1;
    stroke-dashoffset: -1;
  }
  100% {
    opacity: 1;
    stroke-dashoffset: 0;
  }
}

@keyframes fp-monogram-fill {
  from { opacity: 0; }
  to { opacity: 1; }
}


/* Static construction view: preserve the exact source paths, but render both as solid outlines. */
.fp-logo--outline .fp-logo__plate {
  opacity: 1;
  filter: none;
  animation: none;
}

.fp-logo--outline .fp-logo__plate path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.fp-logo--outline .fp-logo__monogram-trace {
  display: none;
  animation: none;
}

.fp-logo--outline .fp-logo__monogram-fill {
  opacity: 1;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  animation: none;
  vector-effect: non-scaling-stroke;
}

@media (prefers-reduced-motion: reduce) {
  .fp-logo__plate,
  .fp-logo__monogram-trace,
  .fp-logo__monogram-fill {
    animation: none;
  }

  .fp-logo__plate {
    opacity: 1;
    filter: none;
  }

  .fp-logo__monogram-trace {
    opacity: 0;
  }

  .fp-logo__monogram-fill {
    opacity: 1;
  }
}
</style>
